mapper.update:
UPDATE forum_activities
SET title = #{title}, summary = #{summary}, start_time = #{startTime}, end_time = #{endTime},
    category = #{category}, tag = #{tag}, user_id = #{userId},
    participant_count = #{participantCount}, status = #{status}, updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT a.id, a.title, a.summary, a.start_time, a.end_time, a.category, a.tag, a.user_id, a.participant_count, a.status, a.created_at, u.nick_name AS user_name, u.avatar AS user_avatar, im.id AS image_id, CONCAT('/image/', im.stored_name) AS image_url, ir.sort FROM forum_activities a LEFT JOIN sys_user u ON a.user_id = u.user_id LEFT JOIN images_record ir ON ir.table_name = 'forum_activity' AND ir.recipe_id = a.id LEFT JOIN image_management im ON ir.image_id = im.id
a.status = 0
AND a.category = #{category}
ORDER BY
a.participant_count DESC, a.created_at DESC a.start_time ASC a.created_at DESC
LIMIT #{offset}, #{limit}
